package com.finanscore.notification.infrastructure;import io.minio.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;@Component public class MinioAttachmentReader{private final MinioClient client;private final String bucket;public MinioAttachmentReader(@Value("${app.minio.endpoint:http://minio:9000}")String endpoint,@Value("${app.minio.access-key:minioadmin}")String access,@Value("${app.minio.secret-key}")String secret,@Value("${app.minio.bucket:scoring-reports}")String bucket){client=MinioClient.builder().endpoint(endpoint).credentials(access,secret).build();this.bucket=bucket;}public byte[] read(String key)throws Exception{try(var in=client.getObject(GetObjectArgs.builder().bucket(bucket).object(key).build())){return in.readAllBytes();}}}